INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY.M_FI_PLANT', 'SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY', 'Thinks a mushroom is a plant because it grows out of the ground.', '{"question":"Which group does a mushroom belong to?","wrong_answer":"Plants","correct_answer":"Fungi"}'::jsonb, 'The child groups living things by where they grow.', 'Offer "Plants" next to the right answer and ask the question again in a new context.', 'Look at a mushroom with a hand lens: it has no green leaves, no flowers and no true roots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY.M_FI_MOULD_DIRT', 'SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY', 'Thinks the fuzzy patch on old bread or an orange is dirt or a stain, not a living thing.', '{"question":"What is the green fuzz that grows on old bread?","wrong_answer":"Dirt that landed on the bread","correct_answer":"A living fungus called mould"}'::jsonb, 'The child only sees the colour and not that it spreads and grows.', 'Offer "Dirt that landed on the bread" next to the right answer and ask the question again in a new context.', 'Keep a damp slice of bread in a closed bag for a week and watch the patch spread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY.M_FI_YEAST_NOT_LIVING', 'SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY', 'Thinks yeast is a powder or a chemical, not a living fungus.', '{"question":"What is yeast, the powder a baker adds to dough?","wrong_answer":"A chemical like baking soda","correct_answer":"A tiny living fungus"}'::jsonb, 'The child meets yeast as dry grains in a packet.', 'Offer "A chemical like baking soda" next to the right answer and ask the question again in a new context.', 'Add warm water and sugar to a spoon of yeast: it froths as the tiny fungi feed and grow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES.M_FF_GREEN_FOOD', 'SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES', 'Thinks fungi make their food in their leaves with sunlight like plants.', '{"question":"How does a mushroom get its food?","wrong_answer":"It makes its own food in its leaves using sunlight","correct_answer":"It takes food from dead or living things"}'::jsonb, 'The child gives every living thing from the garden a plant-like way of feeding.', 'Offer "It makes its own food in its leaves using sunlight" next to the right answer and ask the question again in a new context.', 'Ask: where would a mushroom find sunlight under a rotting log? It is not green.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES.M_FF_ROOTS_LEAVES', 'SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES', 'Thinks a mushroom has roots, stem and leaves like a plant.', '{"question":"What is a mushroom made of?","wrong_answer":"Roots, stem, leaves and flowers","correct_answer":"A stalk and a cap, with thin threads in the soil"}'::jsonb, 'The child draws a mushroom as a small plant.', 'Offer "Roots, stem, leaves and flowers" next to the right answer and ask the question again in a new context.', 'Pull a mushroom apart: a stalk and a cap, thin threads in the soil, and no leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES.M_FF_ALL_EDIBLE', 'SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES', 'Thinks all mushrooms are safe to eat.', '{"question":"A child finds a mushroom growing by the road. Is it safe to eat?","wrong_answer":"Yes, all mushrooms are safe","correct_answer":"No, some are poisonous, so only ones an adult knows are eaten"}'::jsonb, 'The child knows that people eat mushrooms and generalises.', 'Offer "Yes, all mushrooms are safe" next to the right answer and ask the question again in a new context.', 'Name the market mushroom and the toadstool: look the same to a child, but one can make people very sick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE.M_FM_YEAST_GAS', 'SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE', 'Thinks yeast makes dough rise by its own weight or by heat only, not by making a gas.', '{"question":"Why does dough rise when yeast is added?","wrong_answer":"The yeast is heavy and pushes the dough up","correct_answer":"The yeast gives off a gas that makes bubbles in the dough"}'::jsonb, 'The child cannot see the gas.', 'Offer "The yeast is heavy and pushes the dough up" next to the right answer and ask the question again in a new context.', 'Press a risen dough and watch the holes in the baked bread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE.M_FM_ALL_HARMFUL', 'SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE', 'Thinks all fungi are harmful and cause disease or rot.', '{"question":"Which statement about fungi is true?","wrong_answer":"Fungi are all harmful","correct_answer":"Some fungi are useful, such as yeast and edible mushrooms"}'::jsonb, 'The child knows ringworm and mouldy food first.', 'Offer "Fungi are all harmful" next to the right answer and ask the question again in a new context.', 'List what fungi give us: bread, mushrooms, maandazi, medicine and compost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE.M_FM_DECAY_USELESS', 'SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE', 'Thinks rotting is only bad and fungi that rot things have no use.', '{"question":"What good do fungi do when they make a dead log rot?","wrong_answer":"None, rotting is only a loss","correct_answer":"They break dead matter down so it can return to the soil"}'::jsonb, 'The child links rot with smell and waste.', 'Offer "None, rotting is only a loss" next to the right answer and ask the question again in a new context.', 'Dig under a heap of old leaves and find the soft, dark soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH.M_FG_DRY_BEST', 'SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH', 'Thinks mould grows best on dry food in the hot sun.', '{"question":"Where will bread go mouldy first?","wrong_answer":"On a dry plate in the hot sun","correct_answer":"In a damp, warm, covered place"}'::jsonb, 'The child links heat with spoiling and forgets that moisture is needed.', 'Offer "On a dry plate in the hot sun" next to the right answer and ask the question again in a new context.', 'Put two slices in two bags, one with a few drops of water: only the damp one goes mouldy fast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH.M_FG_SCRAPE_SAFE', 'SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH', 'Thinks bread is safe to eat after the mould is scraped off.', '{"question":"A slice of bread has a small patch of mould. What should you do?","wrong_answer":"Scrape it off and eat the rest","correct_answer":"Throw the slice away"}'::jsonb, 'The child sees that only a small part looks bad.', 'Offer "Scrape it off and eat the rest" next to the right answer and ask the question again in a new context.', 'Say the threads of mould spread through the bread where we cannot see them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH.M_FG_AIR_ONLY', 'SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH', 'Thinks mould comes out of the food itself and does not come from spores in the air.', '{"question":"Where does the mould on a stored orange come from?","wrong_answer":"It appears from inside the orange for no reason","correct_answer":"From tiny spores in the air that land on it and grow"}'::jsonb, 'The child cannot see the tiny spores.', 'Offer "It appears from inside the orange for no reason" next to the right answer and ask the question again in a new context.', 'Keep one orange in a sealed jar and one open: the open one goes mouldy first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY.M_FI_ALL_MUSHROOMS_ONE_KIND', 'SCIE.G6.LIVING.FUNGI.FUNGI_IDENTIFY', 'Thinks only mushrooms are fungi, so yeast, moulds and puffballs are something else.', '{"question":"Which of these is a fungus: bread mould, a fern, moss?","wrong_answer":"None of them; only mushrooms are fungi","correct_answer":"Bread mould"}'::jsonb, 'Has learnt "fungus" from mushrooms and has not seen it used for moulds or yeast.', 'Offer "None of them; only mushrooms are fungi" next to the right answer and ask the question again in a new context.', 'Put a mushroom, a mouldy bread slice (sealed) and yeast froth side by side: all feed on other things and grow from spores.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES.M_FF_SPORES_SEEDS', 'SCIE.G6.LIVING.FUNGI.FUNGI_FEATURES', 'Thinks the spores of a mushroom are seeds, like a plant''s.', '{"question":"A mushroom cap drops fine brown dust on paper. What is the dust?","wrong_answer":"Seeds","correct_answer":"Spores"}'::jsonb, 'Knows plants spread by seeds and expects the same from fungi.', 'Offer "Seeds" next to the right answer and ask the question again in a new context.', 'Make a spore print on white paper and look with a hand lens: dust, not seeds with food stores.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE.M_FM_MEDICINE_NOT_FUNGI', 'SCIE.G6.LIVING.FUNGI.FUNGI_IMPORTANCE', 'Does not know that some medicines, such as penicillin, come from fungi.', '{"question":"Where does the medicine penicillin come from?","wrong_answer":"From a plant leaf","correct_answer":"From a mould (a fungus)"}'::jsonb, 'Links medicines with herbs and plants only.', 'Offer "From a plant leaf" next to the right answer and ask the question again in a new context.', 'Tell the story of Fleming finding a mould killing germs on a dish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH.M_FG_FRIDGE_KILLS', 'SCIE.G6.LIVING.FUNGI.FUNGI_MOULD_GROWTH', 'Thinks keeping food in a fridge kills mould for ever.', '{"question":"Bread kept in a fridge for two weeks grows mould. Why?","wrong_answer":"It cannot; the fridge kills mould","correct_answer":"Cold slows mould down but does not stop it for ever"}'::jsonb, 'Thinks cold destroys living things.', 'Offer "It cannot; the fridge kills mould" next to the right answer and ask the question again in a new context.', 'Compare bread in a warm cupboard and in a fridge over two weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY.M_II_SPIDER_INSECT', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY', 'Thinks a spider is an insect.', '{"question":"Which group does a spider belong to?","wrong_answer":"Insects","correct_answer":"The spiders, ticks and mites group"}'::jsonb, 'The child calls every small creature with legs an insect.', 'Offer "Insects" next to the right answer and ask the question again in a new context.', 'Count legs: a spider has eight, an ant has six.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY.M_II_WORM_NOT_ANIMAL_GROUP', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY', 'Thinks a worm, a snail or a starfish is not an invertebrate, or is not an animal group of its own.', '{"question":"Which of these is an invertebrate?","wrong_answer":"None of these, they are not animals","correct_answer":"A snail"}'::jsonb, 'The child only counts animals with legs or bones as animals.', 'Offer "None of these, they are not animals" next to the right answer and ask the question again in a new context.', 'Ask: does a snail have a backbone? Then sort it as in Grade 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY.M_II_CRAB_FISH', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY', 'Thinks crabs and octopuses are fish because they live in the sea.', '{"question":"Which of these sea animals is an invertebrate?","wrong_answer":"All sea animals are fish","correct_answer":"The crab"}'::jsonb, 'The child groups animals by where they live.', 'Offer "All sea animals are fish" next to the right answer and ask the question again in a new context.', 'Ask: does it have a backbone and gills with scales? Compare a tilapia with a crab.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS.M_IC_LEG_COUNT', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS', 'Mixes up the number of legs of insects and spiders, or gives every invertebrate six legs.', '{"question":"How many legs does an insect have?","wrong_answer":"Eight","correct_answer":"Six"}'::jsonb, 'The child remembers "many legs" for small animals.', 'Offer "Eight" next to the right answer and ask the question again in a new context.', 'Draw an ant and a spider side by side and count the legs together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS.M_IC_ALL_SMALL', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS', 'Thinks all invertebrates are tiny.', '{"question":"Which statement about invertebrates is true?","wrong_answer":"All invertebrates are very small","correct_answer":"Some invertebrates are large, such as the octopus"}'::jsonb, 'The child thinks only of ants and flies.', 'Offer "All invertebrates are very small" next to the right answer and ask the question again in a new context.', 'Show a picture of an octopus or a large crab.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS.M_IC_ALL_LEGS', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS', 'Thinks all invertebrates have legs.', '{"question":"Which invertebrate has no legs?","wrong_answer":"All invertebrates have legs","correct_answer":"An earthworm"}'::jsonb, 'The child generalises from insects.', 'Offer "All invertebrates have legs" next to the right answer and ask the question again in a new context.', 'Look at an earthworm and a snail: no legs at all.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE.M_IM_ALL_PESTS', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE', 'Thinks all invertebrates are pests or harmful.', '{"question":"Which statement about invertebrates is true?","wrong_answer":"All invertebrates harm people","correct_answer":"Some invertebrates help people, such as bees and earthworms"}'::jsonb, 'The child remembers mosquitoes, flies and ticks.', 'Offer "All invertebrates harm people" next to the right answer and ask the question again in a new context.', 'List what bees, earthworms and crabs give us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE.M_IM_MOSQUITO_WRONG', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE', 'Mixes up which invertebrate spreads which disease.', '{"question":"Which invertebrate spreads malaria?","wrong_answer":"The housefly","correct_answer":"The female Anopheles mosquito"}'::jsonb, 'The child links every disease with any insect that is a nuisance.', 'Offer "The housefly" next to the right answer and ask the question again in a new context.', 'Match: mosquito with malaria, tick with East Coast fever, housefly with typhoid, tsetse fly with sleeping sickness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE.M_IM_WORMS_HARM', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE', 'Thinks earthworms damage the soil or crops.', '{"question":"What do earthworms do in the soil?","wrong_answer":"They harm the roots of crops","correct_answer":"They loosen the soil so air and water get in"}'::jsonb, 'The child sees only that they live where crops grow.', 'Offer "They harm the roots of crops" next to the right answer and ask the question again in a new context.', 'Dig a spadeful from a garden with worms and from a hard patch: the first is loose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING.M_IH_BARE_HANDS', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING', 'Thinks every small animal is safe to pick up with bare hands.', '{"question":"How should a learner pick up an unknown insect from the compound?","wrong_answer":"With bare hands, it is small","correct_answer":"Not at all, or with a spoon or a jar"}'::jsonb, 'The child thinks that small means harmless.', 'Offer "With bare hands, it is small" next to the right answer and ask the question again in a new context.', 'Name animals that sting or bite: bees, wasps, scorpions, centipedes, some caterpillars.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING.M_IH_CRUSH', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING', 'Thinks it is fine to crush or hurt small animals when studying them.', '{"question":"What should a learner do after looking at a snail in the garden?","wrong_answer":"Crush it so it cannot eat the plants","correct_answer":"Put it back where it was found"}'::jsonb, 'The child thinks of all small animals as pests.', 'Offer "Crush it so it cannot eat the plants" next to the right answer and ask the question again in a new context.', 'Say the school garden has helpers too; look, draw and return the animal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING.M_IH_NO_WASH', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING', 'Thinks washing hands is not needed after touching small animals or soil.', '{"question":"What should be done after handling invertebrates?","wrong_answer":"Nothing, you can go straight to eat","correct_answer":"Wash the hands with soap and water"}'::jsonb, 'The child sees no dirt on the hands.', 'Offer "Nothing, you can go straight to eat" next to the right answer and ask the question again in a new context.', 'Link to handwashing: germs are too small to see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY.M_II_MILLIPEDE_INSECT', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IDENTIFY', 'Thinks a millipede or a centipede is an insect.', '{"question":"Is a millipede an insect?","wrong_answer":"Yes, it is a small crawling animal","correct_answer":"No: it has many body parts and many legs, not three parts and six legs"}'::jsonb, 'Calls every small crawling animal an insect.', 'Offer "Yes, it is a small crawling animal" next to the right answer and ask the question again in a new context.', 'Count the legs of an ant and a millipede with a hand lens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS.M_IC_SNAIL_SHELL_BONE', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_CHARS', 'Thinks a snail''s shell is its skeleton inside, like a backbone.', '{"question":"Is the shell of a snail a backbone?","wrong_answer":"Yes, it is its bone","correct_answer":"No: it is a hard cover outside the soft body; a snail has no backbone"}'::jsonb, 'Equates "hard part" with "bone".', 'Offer "Yes, it is its bone" next to the right answer and ask the question again in a new context.', 'Look at an empty snail shell: it is a hollow outside cover.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE.M_IM_BEES_ONLY_HONEY', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_IMPORTANCE', 'Thinks the only use of bees is honey, and does not know they pollinate crops.', '{"question":"Why do some farmers keep bees near their passion fruit?","wrong_answer":"Only to get honey","correct_answer":"Bees pollinate the flowers, so more fruit forms"}'::jsonb, 'Knows the product, not the service.', 'Offer "Only to get honey" next to the right answer and ask the question again in a new context.', 'Link back to Grade 5 pollination: no bees, fewer passion fruits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING.M_IH_JAR_NO_AIR', 'SCIE.G6.LIVING.INVERTEBRATES.INVERT_HANDLING', 'Thinks a small animal can be kept in a closed jar with no air holes and no food for days.', '{"question":"A learner keeps a grasshopper in a closed jar for a week. What is wrong?","wrong_answer":"Nothing, it will be fine","correct_answer":"It needs air, food and to be put back where it was found"}'::jsonb, 'Does not think of small animals'' needs.', 'Offer "Nothing, it will be fine" next to the right answer and ask the question again in a new context.', 'List what the grasshopper needs (air, food, its home) and set a time limit for study.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS.M_CP_LUNGS_IN', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS', 'Puts the lungs or stomach among the parts of the circulatory system.', '{"question":"Which of these is NOT a part of the circulatory system?","wrong_answer":"The heart","correct_answer":"The stomach"}'::jsonb, 'The child puts every organ in the chest or the trunk together.', 'Offer "The heart" next to the right answer and ask the question again in a new context.', 'Use three colours on a body outline: breathing, digestion and blood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS.M_CP_HEART_PRODUCES', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS', 'Thinks the heart makes the blood or stores it.', '{"question":"What does the heart do with blood?","wrong_answer":"It makes the blood and keeps it","correct_answer":"It pumps the blood round the body"}'::jsonb, 'The child thinks of the heart as the place blood comes from.', 'Offer "It makes the blood and keeps it" next to the right answer and ask the question again in a new context.', 'Feel the pulse at the wrist and count a minute: the heart is pushing blood along.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS.M_CP_VESSEL_NAMES', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS', 'Thinks blood vessels are bones or nerves.', '{"question":"What are the tubes that carry blood called?","wrong_answer":"Nerves","correct_answer":"Blood vessels"}'::jsonb, 'The child has met "veins" in the hand but thinks they are strings.', 'Offer "Nerves" next to the right answer and ask the question again in a new context.', 'Look at the thin blue lines on the inside of the wrist.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS.M_HP_POSITION', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS', 'Thinks the heart is in the stomach or on the far left side, or as big as the whole chest.', '{"question":"About how big is the human heart?","wrong_answer":"As big as the whole chest","correct_answer":"About the size of the owner''s fist"}'::jsonb, 'The child draws the heart on the left side of a doll.', 'Offer "As big as the whole chest" next to the right answer and ask the question again in a new context.', 'Make a fist and place it in the middle of the chest, a little to the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS.M_HP_UPPER_PUMP', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS', 'Thinks the upper chambers do the hard pumping and the lower ones only receive blood.', '{"question":"Which part of the heart pushes blood out with strong squeezes?","wrong_answer":"The upper chambers, the auricles","correct_answer":"The lower chambers, the ventricles"}'::jsonb, 'The child links "upper" with "main".', 'Offer "The upper chambers, the auricles" next to the right answer and ask the question again in a new context.', 'Say the lower chambers have thick walls because they push blood far.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS.M_HP_ONE_ROOM', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS', 'Thinks the heart is one hollow space with no parts.', '{"question":"How many main chambers does the human heart have?","wrong_answer":"One","correct_answer":"Four"}'::jsonb, 'The child draws the heart as a valentine shape.', 'Offer "One" next to the right answer and ask the question again in a new context.', 'Cut a model of the heart from clay and show the four rooms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS.M_CV_SWAP', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS', 'Swaps arteries and veins.', '{"question":"Which vessels carry blood away from the heart?","wrong_answer":"Veins","correct_answer":"Arteries"}'::jsonb, 'The child remembers both names but not the direction.', 'Offer "Veins" next to the right answer and ask the question again in a new context.', 'Remember: Arteries go Away; Veins come Back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS.M_CV_ONE_WAY', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS', 'Thinks the blood leaves the heart, goes to the body and stays there.', '{"question":"What happens to blood after it reaches the toes?","wrong_answer":"It stays in the toes","correct_answer":"It goes back to the heart through the veins"}'::jsonb, 'The child thinks of the body as a place where blood is used up.', 'Offer "It stays in the toes" next to the right answer and ask the question again in a new context.', 'Draw a loop on paper with the heart on the loop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS.M_CV_CAPILLARY_BIG', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS', 'Thinks capillaries are the biggest vessels, or that they carry blood far.', '{"question":"What is special about capillaries?","wrong_answer":"They are the biggest vessels in the body","correct_answer":"They are tiny vessels that pass food and oxygen to the body"}'::jsonb, 'The child thinks of capillaries as hair-like threads.', 'Offer "They are the biggest vessels in the body" next to the right answer and ask the question again in a new context.', 'Say capillary means hair-like in size; show the size on the tip of a pencil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS.M_BC_WHITE_OXYGEN', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS', 'Thinks the white cells carry oxygen.', '{"question":"Which blood cells fight germs?","wrong_answer":"Red blood cells","correct_answer":"White blood cells"}'::jsonb, 'The child remembers only that red cells are important.', 'Offer "Red blood cells" next to the right answer and ask the question again in a new context.', 'Link colour to jobs: red carry, white fight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS.M_BC_PLATELETS', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS', 'Does not know what platelets do or says they carry oxygen.', '{"question":"What do platelets do when you cut your finger?","wrong_answer":"They carry oxygen to the cut","correct_answer":"They help the blood to clot and close the cut"}'::jsonb, 'The child has not met the word.', 'Offer "They carry oxygen to the cut" next to the right answer and ask the question again in a new context.', 'Watch a small cut stop bleeding after a few minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS.M_BC_ALL_RED', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS', 'Thinks blood is made only of red cells.', '{"question":"What is the liquid part of blood called?","wrong_answer":"Blood has no liquid part, it is all red cells","correct_answer":"Plasma, which carries the cells and digested food"}'::jsonb, 'The child has only seen red blood.', 'Offer "Blood has no liquid part, it is all red cells" next to the right answer and ask the question again in a new context.', 'Show a picture of blood left to settle in a tube: a pale yellow layer and a red layer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS.M_CC_CATCHING', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS', 'Thinks high blood pressure or a heart attack can be caught from another person.', '{"question":"Can a child catch high blood pressure from a friend?","wrong_answer":"Yes, it spreads like a cold","correct_answer":"No, it is not caught from other people"}'::jsonb, 'The child links every illness with germs.', 'Offer "Yes, it spreads like a cold" next to the right answer and ask the question again in a new context.', 'Separate illnesses caused by germs (cold, malaria) from those caused by how the body and habits work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS.M_CC_ARTERY_SOFT', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS', 'Thinks hardening of the arteries means the arteries become softer, or that arteries turn into bone.', '{"question":"What happens in hardening of the arteries?","wrong_answer":"The artery walls become soft and thin","correct_answer":"The artery walls become stiff and narrow"}'::jsonb, 'The child confuses the word "hardening" with "becoming bone".', 'Offer "The artery walls become soft and thin" next to the right answer and ask the question again in a new context.', 'Compare a new rubber pipe with an old stiff one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS.M_CC_BP_MEANING', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS', 'Thinks high blood pressure means a lot of blood in the body or red cheeks.', '{"question":"What is high blood pressure?","wrong_answer":"Having more blood than normal in the body","correct_answer":"Blood pushing too hard against the walls of the vessels"}'::jsonb, 'The child reads "pressure" as quantity.', 'Offer "Having more blood than normal in the body" next to the right answer and ask the question again in a new context.', 'Press a hose full of water and feel the push on the sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION.M_CR_REST_ONLY', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION', 'Thinks the heart is kept healthy by resting and not exercising.', '{"question":"Which habit helps to keep the heart strong?","wrong_answer":"Resting all day and avoiding running","correct_answer":"Playing active games such as running and skipping"}'::jsonb, 'The child thinks the heart gets tired like a leg.', 'Offer "Resting all day and avoiding running" next to the right answer and ask the question again in a new context.', 'Say that a heart is a muscle that grows strong with exercise, like other muscles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION.M_CR_OLD_ONLY', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION', 'Thinks only old people need to care about the heart.', '{"question":"When should a person start to care for the heart?","wrong_answer":"Only when they are old","correct_answer":"From childhood, with good habits every day"}'::jsonb, 'The child sees heart illness only in grandparents.', 'Offer "Only when they are old" next to the right answer and ask the question again in a new context.', 'Ask: when do habits like eating chips every day begin?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION.M_CR_SALT_FAT', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION', 'Thinks lots of salt, oil and sugar are good for the heart because they give energy.', '{"question":"Which food should be taken only a little at a time to protect the heart?","wrong_answer":"Plenty of salty and oily snacks","correct_answer":"Salty and oily snacks"}'::jsonb, 'The child links energy with health.', 'Offer "Plenty of salty and oily snacks" next to the right answer and ask the question again in a new context.', 'Look at labels of crisps and soft drinks for salt and sugar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE.M_CR_WATER_SKIP', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE', 'Thinks a routine needs no water or only soft drinks.', '{"question":"Which drink is part of a healthy routine?","wrong_answer":"Soft drinks all day","correct_answer":"Clean water through the day"}'::jsonb, 'The child sees any drink as a drink.', 'Offer "Soft drinks all day" next to the right answer and ask the question again in a new context.', 'Count how many cups of water a learner drinks in the school day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE.M_CR_ONE_HABIT', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE', 'Thinks one good habit, such as exercise, is enough.', '{"question":"Which routine best protects the heart?","wrong_answer":"Exercise only, with any food","correct_answer":"Water, activity, healthy meals and sleep"}'::jsonb, 'The child thinks one habit can do all the work.', 'Offer "Exercise only, with any food" next to the right answer and ask the question again in a new context.', 'Make a daily plan with four boxes and tick one for each habit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE.M_CR_SMOKE_SAFE', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE', 'Thinks smoking or sitting for long hours is harmless for young people.', '{"question":"Which item does NOT belong in a routine for a healthy heart?","wrong_answer":"A walk after school","correct_answer":"Smoking"}'::jsonb, 'The child thinks harm shows only later in life.', 'Offer "A walk after school" next to the right answer and ask the question again in a new context.', 'Say tobacco smoke harms vessels at every age.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS.M_CP_ONLY_HEART', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PARTS', 'Thinks the circulatory system is the heart alone, leaving out the blood and the blood vessels.', '{"question":"Name the parts of the circulatory system.","wrong_answer":"The heart","correct_answer":"The heart, the blood vessels and the blood"}'::jsonb, 'Hears "heart" most and forgets what it pumps and where.', 'Offer "The heart" next to the right answer and ask the question again in a new context.', 'Trace a drop of blood: what pumps it (heart), what carries it (vessels), what it is (blood).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS.M_HP_HEART_SHAPE_LOVE', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.HEART_PARTS', 'Draws or describes the heart as the shape on cards (a symmetrical love shape) and places it in the middle of the belly.', '{"question":"What is the real heart like?","wrong_answer":"A pointed love shape in the belly","correct_answer":"A muscle about the size of a fist, in the chest between the lungs, slightly to the left"}'::jsonb, 'Takes the picture symbol for the real organ.', 'Offer "A pointed love shape in the belly" next to the right answer and ask the question again in a new context.', 'Make a fist: that is about the size of your heart. Feel the beat in the chest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS.M_CV_VEINS_BLUE_BLOOD', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.VESSELS', 'Thinks the blood in veins is blue because veins look blue through the skin.', '{"question":"What colour is the blood in your veins?","wrong_answer":"Blue","correct_answer":"Dark red"}'::jsonb, 'Sees veins as blue under the skin.', 'Offer "Blue" next to the right answer and ask the question again in a new context.', 'When blood is taken from a vein at a clinic, it is dark red in the tube.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS.M_BC_PLASMA_WATER_ONLY', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.BLOOD_COMPONENTS', 'Thinks plasma is just water with nothing in it.', '{"question":"What does plasma carry around the body?","wrong_answer":"Nothing, it is only water","correct_answer":"Digested food, waste and carbon dioxide dissolved in it, and the blood cells"}'::jsonb, 'Sees a clear yellowish liquid and thinks it is plain.', 'Offer "Nothing, it is only water" next to the right answer and ask the question again in a new context.', 'Link to Grade 4 digestion: digested food goes into the blood; plasma carries it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS.M_CC_HEART_ATTACK_ONLY_OLD', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_CONDITIONS', 'Thinks a heart attack has no warning signs, or that chest pain in an adult can be ignored.', '{"question":"An adult has sudden pain in the chest and left arm and is sweating. What should be done?","wrong_answer":"Let them rest and wait","correct_answer":"Call for help at once and get them to a health facility"}'::jsonb, 'Has not learnt the warning signs.', 'Offer "Let them rest and wait" next to the right answer and ask the question again in a new context.', 'Learn the signs of a heart attack and the rule: get help fast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION.M_CR_THIN_SAFE', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_PREVENTION', 'Thinks a thin person cannot get high blood pressure or heart problems.', '{"question":"Can a thin person who eats very salty food and smokes get high blood pressure?","wrong_answer":"No, only fat people get it","correct_answer":"Yes: salt, smoking and stress raise blood pressure in anyone"}'::jsonb, 'Links heart problems only with body size.', 'Offer "No, only fat people get it" next to the right answer and ask the question again in a new context.', 'List the causes: salt, smoking, little exercise, stress; size is only one of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE.M_CR_WEEKEND_EXERCISE', 'SCIE.G6.LIVING.HUMAN_CIRCULATORY_SYSTEM.CIRC_ROUTINE', 'Thinks a lot of exercise once a week is as good as some exercise every day.', '{"question":"Which is better for the heart: a long run once a month, or walking or playing every day?","wrong_answer":"One long run a month","correct_answer":"Some exercise every day"}'::jsonb, 'Thinks the total is what counts, not the habit.', 'Offer "One long run a month" next to the right answer and ask the question again in a new context.', 'Plan a week: 30 to 60 minutes of play or walking each day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES.M_SN_MELT_DISSOLVE', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES', 'Confuses melting with dissolving.', '{"question":"What is it called when ice becomes water?","wrong_answer":"Dissolving","correct_answer":"Melting"}'::jsonb, 'The child sees a solid disappearing into a liquid in both.', 'Offer "Dissolving" next to the right answer and ask the question again in a new context.', 'Melt a candle and dissolve sugar: the candle wax can be set again, the sugar is mixed in the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES.M_SN_EVAP_BOIL', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES', 'Thinks evaporation only happens when water boils.', '{"question":"When does water evaporate?","wrong_answer":"Only when it boils","correct_answer":"At any temperature, faster when warm"}'::jsonb, 'The child sees steam only from a kettle.', 'Offer "Only when it boils" next to the right answer and ask the question again in a new context.', 'Put a wet cloth in the sun and shade: it dries in both, faster in the sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES.M_SN_CONDENSE_MIXUP', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES', 'Mixes up condensation and evaporation, or thinks drops on a cold glass come from inside the glass.', '{"question":"Why do drops form on the outside of a cold bottle?","wrong_answer":"Water leaks through the glass","correct_answer":"Water vapour in the air turns into liquid on the cold surface"}'::jsonb, 'The child cannot see the vapour in the air.', 'Offer "Water leaks through the glass" next to the right answer and ask the question again in a new context.', 'Dry the glass, add ice water, and watch drops return; touch the inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT.M_SH_COLD_MELTS', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT', 'Thinks ice melts because it takes in "cold" from the air.', '{"question":"Why does ice melt in the sun?","wrong_answer":"It takes in cold from the air","correct_answer":"It takes in heat from its surroundings"}'::jsonb, 'The child thinks cold is something that moves.', 'Offer "It takes in cold from the air" next to the right answer and ask the question again in a new context.', 'Hold ice in the hand and ask which way the heat moves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT.M_SH_FREEZE_HEAT', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT', 'Thinks freezing needs heating, or that heat is added when water freezes.', '{"question":"What must happen to water for it to freeze?","wrong_answer":"It must be heated","correct_answer":"It must be cooled, so heat is taken away"}'::jsonb, 'The child thinks every change needs heat.', 'Offer "It must be heated" next to the right answer and ask the question again in a new context.', 'Put a cup in the freezer and ask what the freezer takes away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT.M_SH_STEAM_SMOKE', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT', 'Thinks the cloud above a boiling pot is the gas, or that the water vanishes.', '{"question":"What do we see above a boiling pot?","wrong_answer":"Tiny drops of liquid water, because steam itself cannot be seen","correct_answer":"Water vapour, which we can see"}'::jsonb, 'The child cannot tell vapour from the drops it makes in the cooler air.', 'Offer "Tiny drops of liquid water, because steam itself cannot be seen" next to the right answer and ask the question again in a new context.', 'Hold a cold spoon in the steam and see drops collect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS.M_SA_CLOTHES_SOAK', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS', 'Thinks wet clothes dry because the water soaks into the cloth or into the rope.', '{"question":"What happens to the water when wet clothes dry on a line?","wrong_answer":"It soaks into the rope","correct_answer":"It evaporates into the air"}'::jsonb, 'The child thinks the water has to go somewhere solid.', 'Offer "It soaks into the rope" next to the right answer and ask the question again in a new context.', 'Weigh a wet cloth before and after drying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS.M_SA_CLOUD_SMOKE', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS', 'Thinks clouds are made of smoke or cotton, or that rain is stored in them as water in a tank.', '{"question":"How do clouds form?","wrong_answer":"Smoke from fires gathers in the sky","correct_answer":"Water vapour cools and condenses into tiny drops"}'::jsonb, 'The child sees clouds as solid.', 'Offer "Smoke from fires gathers in the sky" next to the right answer and ask the question again in a new context.', 'Say that the water from lakes and puddles evaporates and cools high in the air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS.M_SA_SALT_SEA', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS', 'Thinks salt from sea water is got by boiling or freezing it, or does not know that the water has to evaporate.', '{"question":"How do salt pans make salt from sea water?","wrong_answer":"The sun makes the water evaporate and leaves the salt","correct_answer":"The sun freezes the water"}'::jsonb, 'The child does not link the sun with evaporation.', 'Offer "The sun makes the water evaporate and leaves the salt" next to the right answer and ask the question again in a new context.', 'Dry a salty water drop on a plate in the sun to see the white salt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES.M_SN_SUBLIMATION_MELT', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_NAMES', 'Calls a solid turning straight into a gas "melting".', '{"question":"Mothballs in a cupboard slowly get smaller and leave no liquid. What is this change called?","wrong_answer":"Melting","correct_answer":"Sublimation"}'::jsonb, 'Uses "melting" for any solid that disappears.', 'Offer "Melting" next to the right answer and ask the question again in a new context.', 'Ask: was there a liquid stage? No liquid means sublimation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT.M_SH_BOILING_HOTTER', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_CHANGE_HEAT', 'Thinks water keeps getting hotter the longer it boils.', '{"question":"Water has been boiling for ten minutes. Is it hotter than when it started to boil?","wrong_answer":"Yes, it gets hotter and hotter","correct_answer":"No: it stays at boiling point; the heat turns water into steam"}'::jsonb, 'Thinks more heating always means a higher temperature.', 'Offer "Yes, it gets hotter and hotter" next to the right answer and ask the question again in a new context.', 'The teacher measures boiling water with a thermometer every two minutes: it stays at about 100 degrees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS.M_SA_PERFUME_GONE', 'SCIE.G6.MATTER.CHANGE_OF_STATE.STATE_APPLICATIONS', 'Thinks perfume or a wet floor "disappears" when it dries, instead of turning into a gas in the air.', '{"question":"A wet floor dries. Where does the water go?","wrong_answer":"It disappears","correct_answer":"It evaporates into the air as water vapour"}'::jsonb, 'Cannot see the gas, so thinks the water is gone.', 'Offer "It disappears" next to the right answer and ask the question again in a new context.', 'Cover a wet patch with a clear cup: drops form inside the cup.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS.M_AC_MOSTLY_OXYGEN', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS', 'Thinks air is mostly oxygen.', '{"question":"Which gas makes up the biggest part of air?","wrong_answer":"Oxygen","correct_answer":"Nitrogen"}'::jsonb, 'The child links air with breathing.', 'Offer "Oxygen" next to the right answer and ask the question again in a new context.', 'Say oxygen is about one fifth of air, nitrogen about four fifths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS.M_AC_ONE_GAS', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS', 'Thinks air is one gas, or is nothing.', '{"question":"What is air?","wrong_answer":"A single gas called oxygen","correct_answer":"A mixture of gases"}'::jsonb, 'The child cannot see air.', 'Offer "A single gas called oxygen" next to the right answer and ask the question again in a new context.', 'Blow into a bag and show that it has weight and takes up space.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS.M_AC_CANDLE_ALL', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS', 'Thinks a burning candle uses up all the air in a closed jar, so water fills the jar.', '{"question":"A candle goes out in a jar placed in water, and the water rises. What does this show?","wrong_answer":"The candle used up all the air in the jar","correct_answer":"The candle used up the oxygen, about one fifth of the air"}'::jsonb, 'The child sees the water rise a long way and thinks the jar is emptied.', 'Offer "The candle used up all the air in the jar" next to the right answer and ask the question again in a new context.', 'Mark the water level and show that it reaches about one fifth of the jar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES.M_AU_CO2_ONLY_OUT', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES', 'Thinks we breathe in only oxygen and breathe out only carbon dioxide, and that CO2 is useless.', '{"question":"What do green plants use carbon dioxide for?","wrong_answer":"Nothing, it is a waste gas","correct_answer":"To make their food using sunlight"}'::jsonb, 'The child hears CO2 only as a waste gas.', 'Offer "Nothing, it is a waste gas" next to the right answer and ask the question again in a new context.', 'Link to Grade 4: leaves make food using sunlight, and need carbon dioxide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES.M_AU_OXYGEN_FUEL', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES', 'Thinks oxygen burns, or that oxygen is the fuel itself.', '{"question":"Why does a fire need air?","wrong_answer":"Oxygen is the fuel that burns","correct_answer":"Oxygen helps the fuel to burn"}'::jsonb, 'The child thinks the gas is what is burnt.', 'Offer "Oxygen is the fuel that burns" next to the right answer and ask the question again in a new context.', 'Cover a candle with a jar: it goes out when the oxygen is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES.M_AU_N_USELESS', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES', 'Thinks nitrogen is useless because we do not breathe it.', '{"question":"Why is nitrogen important to plants?","wrong_answer":"It is not important, we cannot breathe it","correct_answer":"It is changed in the soil into plant food"}'::jsonb, 'The child values a gas only by breathing.', 'Offer "It is not important, we cannot breathe it" next to the right answer and ask the question again in a new context.', 'Mention beans and groundnuts that add plant food to the soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS.M_AP_ONLY_FACTORY', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS', 'Thinks only big factories pollute the air.', '{"question":"Which of these pollutes the air in a home?","wrong_answer":"Only factory chimneys","correct_answer":"Smoke from cooking with firewood or charcoal in a closed room"}'::jsonb, 'The child thinks pollution is always a faraway big thing.', 'Offer "Only factory chimneys" next to the right answer and ask the question again in a new context.', 'Walk around school and list small sources: burning rubbish, a diesel pump, dust.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS.M_AP_ONLY_SMELL', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS', 'Thinks air is clean unless it smells.', '{"question":"Which statement is true?","wrong_answer":"If the air has no smell, it is clean","correct_answer":"Some harmful gases have no smell"}'::jsonb, 'The child uses smell to judge air.', 'Offer "If the air has no smell, it is clean" next to the right answer and ask the question again in a new context.', 'Say that carbon monoxide from a charcoal burner has no smell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS.M_AP_DUST_NOT', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS', 'Thinks dust and smoke from burning rubbish are natural and not pollution.', '{"question":"Is dust from a quarry or a road under repair a pollutant?","wrong_answer":"No, dust is part of the soil","correct_answer":"Yes, it pollutes the air and makes people cough"}'::jsonb, 'The child sees dust as ordinary.', 'Offer "No, dust is part of the soil" next to the right answer and ask the question again in a new context.', 'Cover your nose near a dusty road and see how the air changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS.M_AE_ONLY_NEAR', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS', 'Thinks air pollution only harms people next to the smoke.', '{"question":"How far can air pollution travel?","wrong_answer":"It stays where the smoke is made","correct_answer":"The wind can carry it far from where it started"}'::jsonb, 'The child thinks the air stays still.', 'Offer "It stays where the smoke is made" next to the right answer and ask the question again in a new context.', 'Show smoke from a fire drifting along the wind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS.M_AE_PLANTS_FINE', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS', 'Thinks plants and animals are not harmed by air pollution.', '{"question":"What can acid rain do?","wrong_answer":"Nothing, rain is always good for plants","correct_answer":"Harm plants, buildings and water life"}'::jsonb, 'The child links rain with growing crops.', 'Offer "Nothing, rain is always good for plants" next to the right answer and ask the question again in a new context.', 'Say that smoke gases mix with rain high up and fall as weak acid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS.M_AE_WARM_GOOD', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS', 'Thinks warming of the Earth from smoke gases is only about weather being nice and warm.', '{"question":"What can too much carbon dioxide in the air do?","wrong_answer":"Make the Earth warmer and change the weather","correct_answer":"Make the air cleaner"}'::jsonb, 'The child hears "warmer" as good.', 'Offer "Make the Earth warmer and change the weather" next to the right answer and ask the question again in a new context.', 'Link to floods and drought the child knows from the news.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE.M_AR_BURN_RUBBISH', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE', 'Thinks burning rubbish gets rid of it and cleans the compound.', '{"question":"What is the best way to deal with plastic rubbish?","wrong_answer":"Burn it","correct_answer":"Collect it and take it for recycling or proper disposal"}'::jsonb, 'The child sees the rubbish disappear.', 'Offer "Burn it" next to the right answer and ask the question again in a new context.', 'Smell burning plastic and ask where the smoke goes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE.M_AR_TALL_CHIMNEY', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE', 'Thinks a taller chimney removes the pollution.', '{"question":"Does a taller factory chimney remove the pollution?","wrong_answer":"Yes, the smoke disappears higher up","correct_answer":"No, the smoke still enters the air; filters help"}'::jsonb, 'The child thinks that high means gone.', 'Offer "Yes, the smoke disappears higher up" next to the right answer and ask the question again in a new context.', 'Say the gases are carried by the wind to other places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE.M_AR_TREES_NOT', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE', 'Thinks trees do not help to clean the air.', '{"question":"How do trees help to reduce air pollution?","wrong_answer":"They do not help","correct_answer":"They take in carbon dioxide and trap dust"}'::jsonb, 'The child thinks trees only give shade and fruit.', 'Offer "They do not help" next to the right answer and ask the question again in a new context.', 'Wipe leaves along a dusty road: the cloth turns grey.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS.M_AC_CO2_MOST', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_COMPONENTS', 'Thinks carbon dioxide is the largest part of air because it is spoken of most.', '{"question":"Which gas makes up the largest part of air?","wrong_answer":"Carbon dioxide","correct_answer":"Nitrogen (about four fifths)"}'::jsonb, 'Hears most about carbon dioxide and oxygen and assumes they are biggest.', 'Offer "Carbon dioxide" next to the right answer and ask the question again in a new context.', 'Draw the pie chart: nitrogen about 78 out of 100 parts, oxygen 21, the rest small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES.M_AU_PLANTS_NEED_O2_ONLY', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_USES', 'Thinks plants take in only oxygen from the air, not carbon dioxide for making food.', '{"question":"Which gas from the air do plants use to make food?","wrong_answer":"Oxygen","correct_answer":"Carbon dioxide"}'::jsonb, 'Knows people need oxygen and assumes plants need the same.', 'Offer "Oxygen" next to the right answer and ask the question again in a new context.', 'Link to Grade 4: leaves make food; the raw gas for it is carbon dioxide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS.M_AP_INDOOR_CLEAN', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_POLLUTANTS', 'Thinks the air indoors is always clean, so smoke from a jiko or a paraffin lamp in a closed room is not air pollution.', '{"question":"Is smoke from a jiko inside a closed kitchen air pollution?","wrong_answer":"No, it is inside the house","correct_answer":"Yes: indoor smoke pollutes the air people breathe"}'::jsonb, 'Thinks pollution happens outdoors.', 'Offer "No, it is inside the house" next to the right answer and ask the question again in a new context.', 'Talk about stinging eyes and coughing in a smoky kitchen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS.M_AE_SMOG_ONLY_TOWNS', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_EFFECTS', 'Thinks air pollution cannot harm people in rural areas.', '{"question":"Can burning grass and smoky kitchens harm people in a village?","wrong_answer":"No, villages have clean air","correct_answer":"Yes: smoke causes coughs, chest illness and sore eyes anywhere"}'::jsonb, 'Links pollution only with towns and factories.', 'Offer "No, villages have clean air" next to the right answer and ask the question again in a new context.', 'List smoke sources in a village: burning grass, firewood kitchens, dusty roads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE.M_AR_MASK_FIXES', 'SCIE.G6.MATTER.COMPOSITION_OF_AIR.AIR_REDUCE', 'Thinks wearing a mask is enough to stop air pollution.', '{"question":"What is the best way to reduce smoke in a village?","wrong_answer":"Everyone wears a mask","correct_answer":"Stop burning rubbish, use cleaner stoves and plant trees"}'::jsonb, 'Confuses protecting yourself with stopping the cause.', 'Offer "Everyone wears a mask" next to the right answer and ask the question again in a new context.', 'Sort ideas into "protects me" and "stops the pollution".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS.M_LM_COLOUR_OPAQUE', 'SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS', 'Thinks coloured materials, such as coloured glass or a coloured bag, are opaque.', '{"question":"A red plastic sheet lets light through and you can see a blurred shape behind it. What is it?","wrong_answer":"Opaque, because it is coloured","correct_answer":"Translucent"}'::jsonb, 'The child links colour with blocking light.', 'Offer "Opaque, because it is coloured" next to the right answer and ask the question again in a new context.', 'Hold coloured cellophane to a window and look through it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS.M_LM_TRANSLUCENT_TRANSPARENT', 'SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS', 'Mixes up translucent and transparent.', '{"question":"Frosted glass in a bathroom window lets light in but you cannot see clearly through. What is it?","wrong_answer":"Transparent","correct_answer":"Translucent"}'::jsonb, 'The child hears that both let light through.', 'Offer "Transparent" next to the right answer and ask the question again in a new context.', 'Look at a friend through clear glass and then through frosted glass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS.M_LM_GLASS_ALWAYS', 'SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS', 'Thinks a material is always the same kind, for example all glass is transparent or all paper is opaque.', '{"question":"Which of these is translucent?","wrong_answer":"All paper is opaque","correct_answer":"Tracing paper or tissue paper"}'::jsonb, 'The child sorts by name of the material instead of by its thickness or surface.', 'Offer "All paper is opaque" next to the right answer and ask the question again in a new context.', 'Hold a thin sheet of paper and a thick board to the light.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.SHADOWS.M_SD_MADE_BY_OBJECT', 'SCIE.G6.FORCE_.LIGHT.SHADOWS', 'Thinks the shadow is part of the object or is made by the object, not by blocked light.', '{"question":"What makes a shadow?","wrong_answer":"The object makes it","correct_answer":"The object blocks the light"}'::jsonb, 'The child sees the shadow stuck to the feet of the object.', 'Offer "The object makes it" next to the right answer and ask the question again in a new context.', 'Switch the torch off: the shadow disappears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.SHADOWS.M_SD_SIDE', 'SCIE.G6.FORCE_.LIGHT.SHADOWS', 'Thinks the shadow falls on the same side as the light.', '{"question":"A torch is on the left of a ball. On which side does the shadow fall?","wrong_answer":"The left, beside the torch","correct_answer":"The right, away from the torch"}'::jsonb, 'The child draws the shadow beside the source.', 'Offer "The left, beside the torch" next to the right answer and ask the question again in a new context.', 'Draw the straight ray from the torch to the ball and past it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.SHADOWS.M_SD_SIZE', 'SCIE.G6.FORCE_.LIGHT.SHADOWS', 'Thinks moving the object closer to the light makes the shadow smaller.', '{"question":"What happens to a shadow when the object moves closer to the torch?","wrong_answer":"It becomes smaller","correct_answer":"It becomes larger"}'::jsonb, 'The child thinks that closer means smaller.', 'Offer "It becomes smaller" next to the right answer and ask the question again in a new context.', 'Use a hand and a torch against a wall and move the hand closer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.ECLIPSES.M_EC_CLOUD', 'SCIE.G6.FORCE_.LIGHT.ECLIPSES', 'Thinks an eclipse is caused by clouds or night coming early.', '{"question":"What causes a solar eclipse?","wrong_answer":"Thick clouds cover the Sun","correct_answer":"The Moon moves between the Sun and the Earth"}'::jsonb, 'The child sees the sky darken and thinks of clouds.', 'Offer "Thick clouds cover the Sun" next to the right answer and ask the question again in a new context.', 'Use a ball, a torch and a smaller ball to model it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.ECLIPSES.M_EC_SWAP', 'SCIE.G6.FORCE_.LIGHT.ECLIPSES', 'Swaps solar and lunar eclipses.', '{"question":"In a lunar eclipse, which body is in the middle?","wrong_answer":"The Moon","correct_answer":"The Earth"}'::jsonb, 'The child remembers only the two names.', 'Offer "The Moon" next to the right answer and ask the question again in a new context.', 'Put the three objects in a line and say out loud which is in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.ECLIPSES.M_EC_SAFE', 'SCIE.G6.FORCE_.LIGHT.ECLIPSES', 'Thinks it is safe to look at a solar eclipse with the eyes or through dark glass.', '{"question":"How can a learner watch a solar eclipse safely?","wrong_answer":"Look straight at it for a short time","correct_answer":"Use a pinhole projector or special eclipse glasses, never the bare eye"}'::jsonb, 'The child thinks the Sun is weaker during an eclipse.', 'Offer "Look straight at it for a short time" next to the right answer and ask the question again in a new context.', 'Make a pinhole projector from a box and watch the image of the Sun on a card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_RULE.M_MR_NOT_EQUAL', 'SCIE.G6.FORCE_.LIGHT.MIRROR_RULE', 'Thinks the reflected ray leaves at a different angle from the incoming ray.', '{"question":"A ray hits a plane mirror at 30 degrees to the normal. At what angle to the normal does it leave?","wrong_answer":"60 degrees","correct_answer":"30 degrees"}'::jsonb, 'The child thinks the mirror turns the light.', 'Offer "60 degrees" next to the right answer and ask the question again in a new context.', 'Draw with a protractor and measure.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_RULE.M_MR_FROM_SURFACE', 'SCIE.G6.FORCE_.LIGHT.MIRROR_RULE', 'Measures the angles from the mirror surface and not from the normal.', '{"question":"A ray makes 30 degrees with the mirror surface. What is the angle of incidence?","wrong_answer":"30 degrees","correct_answer":"60 degrees"}'::jsonb, 'The child measures from the flat mirror because it is the visible line.', 'Offer "30 degrees" next to the right answer and ask the question again in a new context.', 'Draw the normal as a dotted line and measure from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_RULE.M_MR_ABSORB', 'SCIE.G6.FORCE_.LIGHT.MIRROR_RULE', 'Thinks a mirror absorbs part of the light or the light goes through the mirror.', '{"question":"What does a plane mirror do to light?","wrong_answer":"It absorbs the light","correct_answer":"It bounces the light back"}'::jsonb, 'The child sees the image "inside" the mirror.', 'Offer "It absorbs the light" next to the right answer and ask the question again in a new context.', 'Shine a torch at a mirror in a dark room and see the spot on the wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE.M_MI_SIZE', 'SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE', 'Thinks the image in a plane mirror is smaller or larger than the object.', '{"question":"How big is the image of a pupil in a plane mirror?","wrong_answer":"Smaller than the pupil","correct_answer":"The same size as the pupil"}'::jsonb, 'The child confuses image with a photograph or with a curved mirror.', 'Offer "Smaller than the pupil" next to the right answer and ask the question again in a new context.', 'Measure your height and the height of your image on the mirror with a ruler.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE.M_MI_DISTANCE', 'SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE', 'Thinks the image is on the surface of the mirror or at a different distance from the mirror.', '{"question":"A pupil stands 2 metres in front of a plane mirror. How far behind the mirror is the image?","wrong_answer":"1 metre","correct_answer":"2 metres"}'::jsonb, 'The child thinks that the image is where the glass is.', 'Offer "1 metre" next to the right answer and ask the question again in a new context.', 'Stand at one, two and three steps and measure how far the image seems.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE.M_MI_UPSIDE', 'SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE', 'Thinks the image is upside down or does not know that left and right swap.', '{"question":"What happens to left and right in a plane mirror image?","wrong_answer":"They stay the same and the image is upside down","correct_answer":"They swap, but the image is upright"}'::jsonb, 'The child says the image is upside down.', 'Offer "They stay the same and the image is upside down" next to the right answer and ask the question again in a new context.', 'Hold up a card with a word and read it in the mirror.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.RAINBOW.M_RB_PAINT', 'SCIE.G6.FORCE_.LIGHT.RAINBOW', 'Thinks a rainbow is a solid arc, painted or a thing in the sky that can be reached.', '{"question":"What is a rainbow?","wrong_answer":"A solid coloured bridge in the sky","correct_answer":"Sunlight split into colours by raindrops"}'::jsonb, 'The child sees it as an object at one place.', 'Offer "A solid coloured bridge in the sky" next to the right answer and ask the question again in a new context.', 'Spray water from a hose in the sun and see a small rainbow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.RAINBOW.M_RB_SUN_FRONT', 'SCIE.G6.FORCE_.LIGHT.RAINBOW', 'Thinks you see a rainbow with the Sun in front of you or when it is only raining.', '{"question":"Where is the Sun when you see a rainbow?","wrong_answer":"In front of you, opposite the rain","correct_answer":"Behind you, with the rain in front"}'::jsonb, 'The child only remembers sun and rain together.', 'Offer "In front of you, opposite the rain" next to the right answer and ask the question again in a new context.', 'Stand with your back to the Sun with a hose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.RAINBOW.M_RB_COLOUR_ORDER', 'SCIE.G6.FORCE_.LIGHT.RAINBOW', 'Gives the wrong order or number of colours.', '{"question":"What colour is at the top of the outer edge of a main rainbow?","wrong_answer":"Violet","correct_answer":"Red"}'::jsonb, 'The child lists the colours in the order of a poem and not of the bow.', 'Offer "Violet" next to the right answer and ask the question again in a new context.', 'Learn the order red, orange, yellow, green, blue, indigo, violet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS.M_LM_THICKNESS_IGNORED', 'SCIE.G6.FORCE_.LIGHT.LIGHT_MATERIALS', 'Thinks the same material is always the same kind, whatever its thickness: one sheet of paper and a thick book both opaque.', '{"question":"Is one thin sheet of tissue paper transparent, translucent or opaque?","wrong_answer":"Opaque, paper blocks light","correct_answer":"Translucent: some light passes through"}'::jsonb, 'Classifies by the material''s name, not by testing.', 'Offer "Opaque, paper blocks light" next to the right answer and ask the question again in a new context.', 'Hold a torch behind one sheet of tissue, then behind a thick pile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.SHADOWS.M_SD_SHADOW_COLOUR', 'SCIE.G6.FORCE_.LIGHT.SHADOWS', 'Thinks a red object makes a red shadow.', '{"question":"A red ball is lit by a torch. What colour is its shadow?","wrong_answer":"Red","correct_answer":"Dark (grey or black): it is where light is blocked"}'::jsonb, 'Thinks the shadow is a copy of the object.', 'Offer "Red" next to the right answer and ask the question again in a new context.', 'Shine a torch on a red and a blue ball: both shadows are dark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.ECLIPSES.M_EC_EVERY_MONTH', 'SCIE.G6.FORCE_.LIGHT.ECLIPSES', 'Thinks a solar eclipse happens every month at new moon.', '{"question":"Why do we not see a solar eclipse every month?","wrong_answer":"We do see one every month","correct_answer":"The Moon usually passes a little above or below the line from the Sun to the Earth"}'::jsonb, 'Has learnt the line-up and thinks it happens each orbit.', 'Offer "We do see one every month" next to the right answer and ask the question again in a new context.', 'Hold the ball (Moon) a little higher than the torch-to-globe line: no shadow on the globe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_RULE.M_MR_NORMAL_ON_MIRROR', 'SCIE.G6.FORCE_.LIGHT.MIRROR_RULE', 'Draws the normal along the mirror instead of at right angles to it.', '{"question":"Where is the normal drawn at a plane mirror?","wrong_answer":"Along the mirror surface","correct_answer":"At right angles (90 degrees) to the mirror where the ray hits"}'::jsonb, 'Mixes up "normal" with the mirror line itself.', 'Offer "Along the mirror surface" next to the right answer and ask the question again in a new context.', 'Stand a set square on the mirror: the normal is its upright side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE.M_MI_REAL_BEHIND', 'SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE', 'Thinks the image is a real picture that could be caught on a screen behind the mirror.', '{"question":"Can you catch the image in a plane mirror on a paper held behind the mirror?","wrong_answer":"Yes, it is there behind the mirror","correct_answer":"No: the image only appears to be behind the mirror; no light goes there"}'::jsonb, 'Sees the image "behind" and expects something to be there.', 'Offer "Yes, it is there behind the mirror" next to the right answer and ask the question again in a new context.', 'Hold paper behind the mirror: nothing appears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LIGHT.RAINBOW.M_RB_ONLY_RAIN', 'SCIE.G6.FORCE_.LIGHT.RAINBOW', 'Thinks rainbows come only from rain and cannot be made with a hose spray or a glass of water.', '{"question":"Can you make a rainbow on a sunny day at school?","wrong_answer":"No, only rain makes rainbows","correct_answer":"Yes: spray water with a hose with the Sun behind you"}'::jsonb, 'Links the rainbow only with the word "rain".', 'Offer "No, only rain makes rainbows" next to the right answer and ask the question again in a new context.', 'Spray a fine mist with the Sun at your back and look into the spray.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY.M_LI_LADDER', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY', 'Calls a ladder, a wheel or a pot a lever.', '{"question":"Which of these is a lever?","wrong_answer":"A ladder","correct_answer":"A pair of pliers"}'::jsonb, 'The child thinks every tool that helps is a lever.', 'Offer "A ladder" next to the right answer and ask the question again in a new context.', 'Ask: is there a bar that turns about a fixed point?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY.M_LI_ONLY_LONG', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY', 'Thinks a lever must be a long stick.', '{"question":"Which of these is a lever?","wrong_answer":"Only a long stick or a crowbar","correct_answer":"Scissors or tweezers"}'::jsonb, 'The child thinks of a crowbar.', 'Offer "Only a long stick or a crowbar" next to the right answer and ask the question again in a new context.', 'Look at scissors: two bars that turn about a screw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY.M_LI_MORE_ENERGY', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY', 'Thinks a lever gives out more energy than is put in.', '{"question":"What does a lever do?","wrong_answer":"Gives more energy than we put in","correct_answer":"Lets a small effort move a big load"}'::jsonb, 'The child thinks easier means free.', 'Offer "Gives more energy than we put in" next to the right answer and ask the question again in a new context.', 'Ask: which end moves farther, the effort end or the load end?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS.M_LP_LOAD_EFFORT', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS', 'Swaps effort and load.', '{"question":"In a wheelbarrow, what is the load?","wrong_answer":"The person lifting the handles","correct_answer":"The soil or bricks in the barrow"}'::jsonb, 'The child thinks the person is the load.', 'Offer "The person lifting the handles" next to the right answer and ask the question again in a new context.', 'Say effort is what you put in and load is what you move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS.M_LP_FULCRUM_HANDLE', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS', 'Thinks the fulcrum is the handle or the part that is held.', '{"question":"On a see-saw, where is the fulcrum?","wrong_answer":"At the seats","correct_answer":"At the middle support the plank turns about"}'::jsonb, 'The child thinks the fulcrum is where force is put.', 'Offer "At the seats" next to the right answer and ask the question again in a new context.', 'Push a ruler over a pencil and point to the pivot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS.M_LP_MOVES', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS', 'Thinks the fulcrum moves with the load.', '{"question":"What does the fulcrum do while a lever works?","wrong_answer":"It moves with the load","correct_answer":"It stays fixed"}'::jsonb, 'The child follows the moving bar.', 'Offer "It moves with the load" next to the right answer and ask the question again in a new context.', 'Place a book on a pencil and see that the pencil stays.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER.M_LE_FAR_FROM_LOAD', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER', 'Thinks that putting the fulcrum closer to the effort makes lifting easier.', '{"question":"A learner lifts a stone with a plank. Where should the fulcrum be to need the least effort?","wrong_answer":"Close to the learner''s hands","correct_answer":"Close to the stone"}'::jsonb, 'The child thinks the nearer the hands, the easier.', 'Offer "Close to the learner''s hands" next to the right answer and ask the question again in a new context.', 'Try a ruler over a pencil: slide the pencil near the load.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER.M_LE_SHORT_ARM', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER', 'Thinks pushing close to the fulcrum needs less effort.', '{"question":"On a door, where should a person push to open it more easily?","wrong_answer":"Close to the hinges","correct_answer":"Far from the hinges, at the handle"}'::jsonb, 'The child thinks near is easier.', 'Offer "Close to the hinges" next to the right answer and ask the question again in a new context.', 'Push a door near the hinge and then at the handle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER.M_LE_FREE_WORK', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER', 'Thinks a lever reduces the work, so the load gets lighter.', '{"question":"What happens to the weight of a load when a lever is used?","wrong_answer":"It gets lighter","correct_answer":"It stays the same, only the effort is smaller"}'::jsonb, 'The child feels the load as lighter.', 'Offer "It gets lighter" next to the right answer and ask the question again in a new context.', 'Weigh the load on a scale before and after using a lever.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS.M_LC_FIRST_ALWAYS', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS', 'Calls every lever a first class lever.', '{"question":"Which class of lever is a wheelbarrow?","wrong_answer":"First class","correct_answer":"Second class"}'::jsonb, 'The child remembers only "first".', 'Offer "First class" next to the right answer and ask the question again in a new context.', 'Find where the load, effort and fulcrum sit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS.M_LC_USE_SIZE', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS', 'Decides the class by size or by use rather than by the middle part.', '{"question":"Which part is in the middle of a third class lever?","wrong_answer":"The fulcrum","correct_answer":"The effort"}'::jsonb, 'The child tries to remember the tool and not the layout.', 'Offer "The fulcrum" next to the right answer and ask the question again in a new context.', 'Draw a bar with three dots and write F, L, E in each order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS.M_LC_THIRD_SECOND', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS', 'Mixes up second and third class levers.', '{"question":"Which class of lever is a pair of tweezers?","wrong_answer":"Second class","correct_answer":"Third class"}'::jsonb, 'The child thinks that both have the fulcrum at one end.', 'Offer "Second class" next to the right answer and ask the question again in a new context.', 'Squeeze tweezers in the middle and see where the pivot is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY.M_LI_HANDLE_ANY', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_IDENTIFY', 'Thinks any object with a handle is a lever, such as a cup or a bucket.', '{"question":"Is a bucket with a handle a lever?","wrong_answer":"Yes, it has a handle","correct_answer":"No: it does not turn about a fixed point to move a load"}'::jsonb, 'Links levers with handles.', 'Offer "Yes, it has a handle" next to the right answer and ask the question again in a new context.', 'Test: does the tool turn on a fixed point (fulcrum) to move a load?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS.M_LP_FULCRUM_ALWAYS_MIDDLE', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_PARTS', 'Thinks the fulcrum is always in the middle, like a see-saw.', '{"question":"Where is the fulcrum of a wheelbarrow?","wrong_answer":"In the middle of the handles","correct_answer":"At the wheel"}'::jsonb, 'Has learnt levers from a see-saw.', 'Offer "In the middle of the handles" next to the right answer and ask the question again in a new context.', 'Lift a wheelbarrow: what does it turn on?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER.M_LE_LONGER_HARDER', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_EASIER', 'Thinks a longer handle makes it harder to lift a load.', '{"question":"Is it easier to lift a stone with a short bar or a long bar?","wrong_answer":"A short bar, less to hold","correct_answer":"A long bar, with the effort far from the fulcrum"}'::jsonb, 'Thinks a longer bar is heavier and harder.', 'Offer "A short bar, less to hold" next to the right answer and ask the question again in a new context.', 'Try lifting a heavy box with a short stick and a long stick on the same stone fulcrum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS.M_LC_SCISSORS_SECOND', 'SCIE.G6.FORCE_.LEVERS_AS_SIMPLE_MACHINE.LEVER_CLASS', 'Puts a pair of scissors or pliers in the second class because they cut or grip.', '{"question":"In which class is a pair of scissors?","wrong_answer":"Second class","correct_answer":"First class: the fulcrum (the pivot) is in the middle"}'::jsonb, 'Classifies by what the tool does instead of by the middle part.', 'Offer "Second class" next to the right answer and ask the question again in a new context.', 'Mark F, E and L on the scissors: the pivot is between the handles and the blades.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES.M_ST_PULLEY', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES', 'Calls a pulley or a see-saw a slope.', '{"question":"Which of these is a slope?","wrong_answer":"A see-saw","correct_answer":"A ramp"}'::jsonb, 'The child names any machine from the unit.', 'Offer "A see-saw" next to the right answer and ask the question again in a new context.', 'Look for a tilted flat surface.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES.M_ST_FLAT_ROAD', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES', 'Thinks a flat road is a slope.', '{"question":"Which of these is NOT a slope?","wrong_answer":"A road winding up a hill","correct_answer":"A flat road on level ground"}'::jsonb, 'The child thinks that every road is a slope.', 'Offer "A road winding up a hill" next to the right answer and ask the question again in a new context.', 'Roll a ball on a flat table and on a tilted board.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES.M_ST_WEDGE', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES', 'Does not know that a wedge such as an axe or a knife is a slope.', '{"question":"Which tool is a slope in the shape of a wedge?","wrong_answer":"A hammer","correct_answer":"An axe"}'::jsonb, 'The child sees the sharp edge only.', 'Offer "A hammer" next to the right answer and ask the question again in a new context.', 'Draw the side view of an axe: two slopes meeting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER.M_SE_STEEP_EASIER', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER', 'Thinks a steeper slope needs less effort.', '{"question":"Which ramp needs the least effort to push a loaded wheelbarrow up?","wrong_answer":"The steepest ramp","correct_answer":"The long, gentle ramp"}'::jsonb, 'The child thinks that shorter means easier.', 'Offer "The steepest ramp" next to the right answer and ask the question again in a new context.', 'Pull a toy car up a steep plank and then a long gentle one with a spring balance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER.M_SE_LIGHTER', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER', 'Thinks the load becomes lighter on a slope.', '{"question":"What happens to the weight of a drum on a ramp?","wrong_answer":"It becomes lighter","correct_answer":"It stays the same, only the push needed is smaller"}'::jsonb, 'The child feels the push as less weight.', 'Offer "It becomes lighter" next to the right answer and ask the question again in a new context.', 'Weigh the drum on a scale on the ground and on the ramp.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER.M_SE_SHORTER_WAY', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER', 'Thinks a slope saves distance.', '{"question":"Compared with lifting a load straight up, how far is it moved along a ramp?","wrong_answer":"A shorter distance","correct_answer":"A longer distance"}'::jsonb, 'The child thinks easier also means shorter.', 'Offer "A shorter distance" next to the right answer and ask the question again in a new context.', 'Measure the straight height and the ramp length with a string.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES.M_ST_SCREW_NOT_SLOPE', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_TYPES', 'Does not see a screw or a winding road as a slope.', '{"question":"Is a screw a kind of slope?","wrong_answer":"No, it is a nail with lines","correct_answer":"Yes: its thread is a slope wound round a rod"}'::jsonb, 'Does not see the slope in a curled shape.', 'Offer "No, it is a nail with lines" next to the right answer and ask the question again in a new context.', 'Wind a paper triangle round a pencil: the edge makes a screw thread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER.M_SE_SLOPE_LESS_WORK', 'SCIE.G6.FORCE_.SLOPES_AS_SIMPLE_MACHINE.SLOPE_EASIER', 'Thinks a slope reduces the work done, not only the effort.', '{"question":"Does using a ramp to load a drum onto a lorry mean less work is done?","wrong_answer":"Yes, less work","correct_answer":"No: less effort is needed, but over a longer distance"}'::jsonb, 'Feels the push is easier and thinks the whole job is smaller.', 'Offer "Yes, less work" next to the right answer and ask the question again in a new context.', 'Measure: a longer ramp, less pull, more distance pushed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
